import type { AlarmSound } from '../../electron/shared/types'

/**
 * The three alarm sounds as embedded data URIs — no external audio
 * assets needed. Each is a short (~1s) synthesized tone loop with
 * click-avoiding fade envelopes baked into the waveform itself, so the
 * runtime code that plays them stays simple (see useAlarm.ts).
 */

// Re-exported so renderer code can keep importing the alarm sound type
// from the module that owns the sounds themselves.
export type { AlarmSound }

const CLASSIC_BEEP = 'data:audio/wav;base64,'

const GENTLE_CHIME = 'data:audio/wav;base64,'

const URGENT_SIREN = 'data:audio/wav;base64,'

export const ALARM_SOUND_OPTIONS: { value: AlarmSound; label: string }[] = [
  { value: 'classic-beep', label: 'Classic Beep' },
  { value: 'gentle-chime', label: 'Gentle Chime' },
  { value: 'urgent-siren', label: 'Urgent Siren' },
]

export const ALARM_SOUND_SOURCES: Record<AlarmSound, string> = {
  'classic-beep': CLASSIC_BEEP,
  'gentle-chime': GENTLE_CHIME,
  'urgent-siren': URGENT_SIREN,
}
